    await page.keyboard.down('ArrowRight');
    await sleep(900);
    await page.keyboard.up('ArrowRight');

    // 3) walk straight for 2s
    await page.keyboard.down('ArrowUp');
    await sleep(2000);
    await page.keyboard.up('ArrowUp');

    // 4) turn right ~135deg (hold ~1350ms)
    await page.keyboard.down('ArrowRight');
    await sleep(1350);
    await page.keyboard.up('ArrowRight');

    // 5-9) Five intervals: walk 0.5s and take screenshot each time
    for (let i = 1; i <= 5; i++) {
        await page.keyboard.down('ArrowUp');
        await sleep(500);
        await page.keyboard.up('ArrowUp');
        await sleep(100); // give frame a moment
        await capture(`walk_step_${i}`);
    }

    await browser.close();
    console.log('done');
})();

